pecialchars($item['title']??'หนังสือ')?></div><div class="card-item-price"><?=$isCancelled?'฿0.00':'฿'.number_format($item['price_at_purchase'],2)?></div></div><div class="card-item-qty">x<?=$item['quantity']?></div></div><?php endforeach;if(count($o['items'])>1):?><div style="text-align:center;padding:12px;border-bottom:1px solid #f0e8e1;color:#746b65;font-size:14px;background:#fdfdfd">ดูสินค้าเพิ่มเติมอีก <?=count($o['items'])-1?> รายการ</div><?php endif;?><div class="card-summary"><span class="total-items"><?=$total_items?> ชิ้น</span><span class="commission" style="color:<?=$isCancelled?'#aaa':'#d35400'?>;font-weight:600">รายได้สุทธิ: ฿<?=number_format($netIncome,2)?></span></div><div class="card-footer"><div class="order-date">สั่งซื้อเมื่อ <?=date('d-m-Y H:i',strtotime($o['created_at']))?></div><div class="card-actions"><?php if($o['payment_status']==='paid'&&!in_array($o['shipping_status'],['shipped','delivered','cancelled','returned'],true)):?><button class="btn ship-btn" data-order="<?=$o['order_id']?>" data-number="<?=htmlspecialchars($o['order_number'])?>">อัปโหลดข้อมูลการจัดส่ง</button><?php endif;?></div></div></div><?php endforeach;?></div><?php endif;?></main></div><?php require __DIR__.'/../components/footer.php';?>
