NumberInfo"></span></div><div style="display:flex;justify-content:space-between;margin-bottom:8px"><span>สั่งซื้อเมื่อ</span><span id="dDateInfo"></span></div></div><div style="background:#fff;padding:16px 20px;display:flex;gap:10px;justify-content:flex-end" id="statusForms"></div><button class="btn close" style="margin:20px;width:calc(100% - 40px)" type="button" data-close>ปิดหน้าต่าง</button></div></div>
