<script>
const csrf=<?=json_encode($_SESSION['seller_market_csrf'])?>,detailModal=document.getElementById('detailModal'),shippingModal=document.getElementById('shippingModal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function openDetail(el){if(event.target.closest("button"))return;const d=JSON.parse(el.dataset.detail),o=d.order;const h=document.getElementById("dHeader");document.getElementById("dStatusText").textContent=d.statusText;document.getElementById("dStatusSub").textContent=o.shipping_status==="delivered"?"ผู้ซื้อยืนยันได้รับสินค้า":"กรุณาตรวจสอบข้อมูล";h.style.background=d.statusClass==="done"?"#39703a":d.statusClass==="wait"?"#e67e22":d.statusClass==="paid"?"#bc443d":d.statusClass==="ship"?"#d35400":"#888";document.getElementById("dSubtotal").textContent="฿"+Number(d.subtotal).toLocaleString(undefined,{minimumFractionDigits:2});document.getElementById("dShippingFee").textContent="฿"+Number(d.shippingFee??0).toLocaleString(undefined,{minimumFractionDigits:2});document.getElementById("dCommission").textContent="-฿"+Number(d.commission).toLocaleString(undefined,{minimumFractionDigits:2});document.getElementById("dNetIncome").textContent="฿"+Number(d.net).toLocaleString(undefined,{minimumFractionDigits:2});document.getElementById("dNumberInfo").textContent=o.order_number;document.getElementById("dDateInfo").textContent=o.created_at;document.getElementById("dBuyer").textContent=o.shipping_name+" · "+o.shipping_phone;document.getElementById("dAddress").textContent=o.shipping_address;document.getElementById("dItems").innerHTML=o.items.map(i=>`<div style="display:flex;gap:12px;margin-bottom:12px;align-items:center"><img src="${i.image_cover?(i.image_cover.startsWith('uploads')?'/pages/'+i.image_cover:'/assets/image/books/'+i.image_cover):'/assets/image/placeholder.png'}" style="width:48px;height:64px;object-fit:cover;border-radius:4px"><div style="flex:1"><div style="font-weight:600;color:#333;font-size:15px">${esc(i.title)}</div><div style="color:#777;font-size:14px">x${i.quantity}</div></div><strong style="color:${d.isCancelled?'#aaa':'#d35400'}">${d.isCancelled?'฿0.00':'฿'+Number(i.price_at_purchase).toLocaleString(undefined,{minimumFractionDigits:2})}</strong></div>`).join("");const img=document.getElementById("dSlip"),none=document.getElementById("noSlip");if(d.slip){img.src=d.slip;img.classList.remove("hidden");none.classList.add("hidden")}else{img.classList.add("hidden");none.classList.remove("hidden")}let buttons="";if(o.shipping_status==="shipped")buttons+=form(o.order_id,"delivered","จัดส่งสำเร็จ");if(!["delivered","cancelled","returned"].includes(o.shipping_status))buttons+=form(o.order_id,"cancelled","ยกเลิกคำสั่งซื้อ","outline");document.getElementById("statusForms").innerHTML=buttons;detailModal.classList.add("open");}
function form(id,status,label,cls=''){return `<form method="post"><input type="hidden" name="csrf_token" value="${csrf}"><input type="hidden" name="order_id" value="${id}"><input type="hidden" name="status" value="${status}"><button class="btn ${cls}" name="update_status">${label}</button></form>`}
document.querySelectorAll('.ship-btn').forEach(btn=>btn.addEventListener('click',()=>{document.getElementById('shipOrderId').value=btn.dataset.order;document.getElementById('shipNumber').textContent='คำสั่งซื้อ #'+btn.dataset.number;shippingModal.classList.add('open')}));
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('.modal').classList.remove('open')));document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('open')}));
</script></body></html>
